```js
/**
 * Fetch one skill resource as raw bytes.
 *
 * The bridge exposes two read paths and they are not interchangeable:
 *   files/read      returns a JSON envelope ({ code, data: { content, encoding } })
 *   files/download  returns the resource's raw bytes, which is what a file
 *                   on disk needs
 * The tool description only documents `files/read`, and `curl -o` does not
 * change that — `-o` is a client flag, the server never sees it, and the
 * bridge routes by subpath. So this uses `files/download`.
 *
 * The other trap: an empty resource is legal (Core's schema allows a zero-byte
 * `content`), but the download branch tests `!parsed.data?.content` and a falsy
 * empty string falls through to returning the whole JSON envelope. So success
 * may arrive as an envelope too. We decode it: a string `content` — empty
 * included — is content; a missing / non-string `content`, or any `code !== 0`,
 * is an error whose envelope message must not be swallowed.
 *
 * Team experience: evaluation skill `eval-skill-resource-download`
 * (token bt-pvxahxcppk3).
 *
 * @param {{ skillId: string, path: string, bridgeBase: string,
 *           fetcher?: typeof fetch }} args
 * @returns {Promise<Buffer>} the resource bytes (zero-length for an empty file)
 */
export async function fetchResource({ skillId, path, bridgeBase, fetcher } = {}) {
  const doFetch = fetcher ?? globalThis.fetch;
  if (typeof doFetch !== "function") throw new Error("fetchResource: no fetcher available");
  if (!bridgeBase) throw new Error("fetchResource: bridgeBase is required");
  const url = `${String(bridgeBase).replace(/\/+$/, "")}/files/download`;
  const res = await doFetch(url, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ skill_id: skillId, path }),
  });
  const bytes = await readBytes(res);

  const envelope = parseEnvelope(bytes);
  if (envelope) {
    if (envelope.code !== 0) throw envelopeError(envelope);
    const data = envelope.data;
    if (!data || typeof data.content !== "string") {
      // `code: 0` with no usable content is a malformed envelope, not an empty
      // file: fields missing or the wrong type are the only real anomalies.
      throw envelopeError({ code: envelope.code, message: envelope.message ?? "malformed envelope: data.content is not a string", data });
    }
    return decodeContent(data.content, data.encoding);
  }
  if (res && res.ok === false) {
    throw new Error(`fetchResource: ${url} responded HTTP ${res.status}${res.statusText ? ` ${res.statusText}` : ""}`);
  }
  return bytes;
}
