    return decodeContent(data.content, data.encoding);
  }
  if (res && res.ok === false) {
    throw new Error(`fetchResource: ${url} responded HTTP ${res.status}${res.statusText ? ` ${res.statusText}` : ""}`);
  }
  return bytes;
